// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {RewardVault} from "../src/RewardVault.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    RewardVault c;

    function setUp() public {
        c = new RewardVault();
    }

    function _test(uint256 amt, uint256 r1, uint256 r2) internal {
        amt = bound(amt, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(amt > 0);
        vm.assume(r1 != r2);
        vm.assume(r1 <= type(uint256).max / amt);
        vm.assume(address(this).balance >= amt);
        vm.assume(r1 == c.rewardRate());
        uint256 balBefore = address(this).balance;
        try c.deposit{value: amt}() {} catch { return; }
        try c.setRewardRate(r1) {} catch { return; }
        uint256 claimed;
        try c.claim() returns (uint256 __r) { claimed = __r; } catch { return; }
        try c.setRewardRate(r2) {} catch { return; }
        assertTrue(claimed == amt * r1);
    }

    function testFuzz_test(uint256 amt, uint256 r1, uint256 r2) public {
        _test(amt, r1, r2);
    }

    receive() external payable {}
}
